<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
class WebhookEndpoint extends Model {use HasFactory;protected $fillable=['user_id','name','token','enabled'];protected $casts=['enabled'=>'boolean'];protected $hidden=['token'];public function user():BelongsTo{return $this->belongsTo(User::class);}public function requests():HasMany{return $this->hasMany(WebhookRequest::class);}public function getUrlAttribute():string{return route('webhook.receive',['endpoint'=>$this->token]);}}